-- Generated by drizzle-kit, comments added by hand: each index names the query it serves
-- (PLAN.md §5). Lists use keyset pagination: WHERE ... AND (created_at, id) < ($cursor)
-- ORDER BY created_at DESC, id DESC LIMIT n. DESC NULLS FIRST is what plain DESC means, so
-- the index returns rows already in that order (no sort step).

-- Dispatcher summary per call center: WHERE call_center_id = $1 ORDER BY distributed_at DESC
CREATE INDEX "distributions_call_center_distributed_at_idx" ON "distributions" USING btree ("call_center_id","distributed_at" DESC NULLS FIRST);--> statement-breakpoint
-- Reducer: SELECT ... FROM lead_status_events WHERE lead_id = $1 ORDER BY event_ts, ...
CREATE INDEX "lead_status_events_lead_id_event_ts_idx" ON "lead_status_events" USING btree ("lead_id","event_ts");--> statement-breakpoint
-- ADMIN default list, "leads today" and period filter: ORDER BY created_at DESC, id DESC
CREATE INDEX "leads_created_at_id_idx" ON "leads" USING btree ("created_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
-- OPERATOR list (scope from the session) and call center filter: WHERE call_center_id = $1
CREATE INDEX "leads_call_center_created_at_id_idx" ON "leads" USING btree ("call_center_id","created_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
-- Status filter and sales count: WHERE status = $1
CREATE INDEX "leads_status_created_at_id_idx" ON "leads" USING btree ("status","created_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
-- Product filter, or product + funnel (a funnel always implies its product): WHERE product_id = $1 [AND funnel_id = $2]
CREATE INDEX "leads_product_funnel_created_at_id_idx" ON "leads" USING btree ("product_id","funnel_id","created_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
-- Source filter: WHERE source = $1
CREATE INDEX "leads_source_created_at_id_idx" ON "leads" USING btree ("source","created_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
-- Pending queue (redispatch-pending, pending count): WHERE call_center_id IS NULL.
-- Partial, so it only holds the few undistributed leads.
CREATE INDEX "leads_pending_idx" ON "leads" USING btree ("id") WHERE "leads"."call_center_id" IS NULL;
